"""The files the web build and its tests take from the seed, generated by the engine itself.

    python -m dgate.readiness.export <repository root>      write them
    python -m dgate.readiness.export <repository root> --check    fail if a file is out of date

  web/lib/mock/requirements.json     the catalogue, each requirement and the rules, as the API serves
                                     them: what the site shows when it is built without an API (CI)
  web/e2e/fixtures/assess-<k>.json   the API's answer for the two test profiles of the wizard e2e specs
  web/e2e/fixtures/request-<k>.json  the request body the wizard has to send for those answers

A test (tests/unit/test_readiness_export.py) runs the `--check`, so the fixtures cannot drift from the
rules: the e2e specs state verdicts that the Python engine produced from the same seed.
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Any

from . import api
from .engine import Profile
from .seed import load_file

FIXED_TIME = "2026-10-17T12:00:00+00:00"
STATUS_CODES = ["REQ-NCAGE", "REQ-PIC", "REQ-ISO9001", "REQ-EN9100", "REQ-AQAP2110", "REQ-AQAP2310", "REQ-EXPORT"]
ES_ONLY = ["REQ-REOCE", "REQ-FSC-ES"]

# The answers a person gives in the wizard, for the two scenarios the e2e specs run.
PROFILES: dict[str, tuple[dict[str, Any], dict[str, str]]] = {
    "ua": ({"country": "UA", "legal_form": "legal_person", "executive_management_country": "UA", "third_country_control": "no",
            "ua_non_government_controlled_area": False, "non_eu_component_cost_pct": 20.0,
            "restricted_third_country_component": False, "components_from_ua_or_eea_efta": False,
            "safe_role": "contractor", "handles_classified": False,
            "product_regime": "dual_use", "export_intent": "outside_eu"},
           {code: "not_held" for code in STATUS_CODES}),
    # the Ukrainian company after it marked its PIC as done in the roadmap: the answer the page re-scores to
    "ua-pic": ({"country": "UA", "legal_form": "legal_person", "executive_management_country": "UA", "third_country_control": "no",
                "ua_non_government_controlled_area": False, "non_eu_component_cost_pct": 20.0,
                "restricted_third_country_component": False, "components_from_ua_or_eea_efta": False,
                "safe_role": "contractor", "handles_classified": False,
                "product_regime": "dual_use", "export_intent": "outside_eu"},
               {**{code: "not_held" for code in STATUS_CODES}, "REQ-PIC": "held"}),
    "es": ({"country": "ES", "legal_form": "legal_person", "executive_management_country": "ES", "third_country_control": "no",
            "ua_non_government_controlled_area": None, "non_eu_component_cost_pct": 10.0,
            "restricted_third_country_component": False, "components_from_ua_or_eea_efta": False,
            "safe_role": "contractor", "handles_classified": True,
            "product_regime": "military", "export_intent": "outside_eu"},
           {**{code: "not_held" for code in STATUS_CODES + ES_ONLY}, "REQ-ISO9001": "held"}),
}


def build() -> dict[str, Any]:
    """Every generated file, by its path relative to the repository root."""
    c = load_file()
    files: dict[str, Any] = {
        "web/lib/mock/requirements.json": {
            "catalogue": api.catalogue_payload(c),
            "requirements": {code: api.requirement_payload(c, code) for code in sorted(c.requirements)},
            "programmes": api.programmes_payload(c),
        },
    }
    for key, (profile, statuses) in PROFILES.items():
        body = {"profile": profile, "statuses": statuses}
        answer = api.assess_payload(c, Profile(**profile), statuses)
        answer["generatedAt"] = FIXED_TIME
        files[f"web/e2e/fixtures/request-{key}.json"] = body
        files[f"web/e2e/fixtures/assess-{key}.json"] = answer
    return files


def render(data: Any) -> str:
    return json.dumps(data, indent=1, ensure_ascii=False, sort_keys=True) + "\n"


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("root", type=Path)
    ap.add_argument("--check", action="store_true")
    a = ap.parse_args(argv)
    stale = []
    for rel, data in build().items():
        path = a.root / rel
        text = render(data)
        if a.check:
            if not path.exists() or path.read_text(encoding="utf-8") != text:
                stale.append(rel)
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding="utf-8", newline="\n")
            print(f"wrote {rel}")
    if stale:
        print("out of date (run python -m dgate.readiness.export <root>): " + ", ".join(stale))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
